"""Generated by make_engines.py: certificate engine for chart C1pp (same logic as nb_cert.py).
Coefficient enclosure on a box: centre values and gradient (chain rule through the atoms) from coef_val at the
centre atoms; the variation of each gradient component over the box is bounded by
Pabs(|a_c| + Da) - Pabs(|a_c|) applied to its atom polynomial; |coefficient| <= Pabs(|a_c| + Da) on the box.
Atoms are nonnegative on the chart domain, with Da = max(hi - a_c, a_c - lo) from monotone enclosures."""
import math
import numpy as np
from numba import njit
from nbcoef_C1pp import coef_val, coef_abs
from nb_cert import arc_signs, dp_count

LIMIT = 11          # parity lemma: an even count <= 11 is <= 10
ARC_PAD = 1e-12     # absolute inflation of every arc half-width (arcs overlap; union covers the circle)

@njit(cache=True)
def atoms_box(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi):
    ec = 0.5 * (x0lo + x0hi); lc = 0.5 * (x1lo + x1hi); wc = 0.5 * (x2lo + x2hi)
    lo = np.empty(6); hi = np.empty(6); ac = np.empty(6)
    lo[0] = x0lo; hi[0] = x0hi; ac[0] = ec
    lo[1] = x1lo; hi[1] = x1hi; ac[1] = lc
    emax = x0hi * x1hi * x1hi; emin = x0lo * x1lo * x1lo; ecen = ec * lc * lc
    lo[2] = math.sqrt(1 - emax * emax); hi[2] = math.sqrt(1 - emin * emin); ac[2] = math.sqrt(1 - ecen * ecen)
    lo[3] = 1 / hi[2]; hi[3] = 1 / lo[2]; ac[3] = 1 / ac[2]
    lo[4] = math.sin(x2lo); hi[4] = math.sin(x2hi); ac[4] = math.sin(wc)
    lo[5] = math.cos(x2hi); hi[5] = math.cos(x2lo); ac[5] = math.cos(wc)
    return ac, lo, hi


@njit(cache=True)
def box_coeffs(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi):
    ac, lo, hi = atoms_box(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi)
    na = ac.size
    da = np.empty(na); aa = np.empty(na); ab = np.empty(na)
    for i in range(na):
        da[i] = max(hi[i] - ac[i], ac[i] - lo[i]) * (1 + 1e-12) + 1e-15 * (abs(ac[i]) + 1.0)
        aa[i] = abs(ac[i]); ab[i] = aa[i] + da[i]
    val = np.zeros((4, 2, 2, 7)); a0 = np.zeros((4, 2, 2, 7)); a1 = np.zeros((4, 2, 2, 7))
    coef_val(ac, val); coef_abs(aa, a0); coef_abs(ab, a1)
    cmid = np.empty((2, 2, 7)); crad = np.empty((2, 2, 7)); cmax = np.empty((2, 2, 7))
    dcen = np.empty((3, 2, 2, 7)); dwid = np.empty((3, 2, 2, 7))
    for f in range(2):
        for pt in range(2):
            for k in range(7):
                cmid[f, pt, k] = val[0, f, pt, k]
                crad[f, pt, k] = 1e-13 * a0[0, f, pt, k] + 1e-300
                cmax[f, pt, k] = a1[0, f, pt, k] * (1 + 1e-12)
                for v in range(3):
                    dcen[v, f, pt, k] = val[1 + v, f, pt, k]
                    dwid[v, f, pt, k] = (a1[1 + v, f, pt, k] - a0[1 + v, f, pt, k]) * (1 + 1e-12) + 1e-13 * a1[1 + v, f, pt, k]
    rr = np.empty(3)
    rr[0] = 0.5 * (x0hi - x0lo) * (1 + 1e-12) + 1e-15 * (abs(0.5 * (x0lo + x0hi)) + 1.0)   # padded mean-value radii
    rr[1] = 0.5 * (x1hi - x1lo) * (1 + 1e-12) + 1e-15 * (abs(0.5 * (x1lo + x1hi)) + 1.0)
    rr[2] = 0.5 * (x2hi - x2lo) * (1 + 1e-12) + 1e-15 * (abs(0.5 * (x2lo + x2hi)) + 1.0)
    return cmid, crad, dcen, dwid, cmax, rr


@njit(cache=True)
def certify_box(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi, t0, t1, J, M0, rounds):
    cmid, crad, dcen, dwid, cmax, rr = box_coeffs(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi)
    left = np.arange(M0) * (2 * math.pi / M0)
    width = np.full(M0, 2 * math.pi / M0)
    total = 999
    prev = 10 ** 9
    stall = 0
    for rd in range(rounds + 1):
        sg, hopeless = arc_signs(cmid, crad, dcen, dwid, cmax, rr, t0, t1, left + width / 2, width / 2 + ARC_PAD, J)
        total = dp_count(sg)
        if total <= LIMIT:
            return True, total
        if rd == rounds or hopeless or left.size > 4096:
            break
        if total >= prev:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
        prev = total
        nsel = 0
        for i in range(left.size):
            if sg[0, i] == 0:
                nsel += 1
        if nsel == 0:
            break
        nl = np.empty(left.size + nsel); nw = np.empty(left.size + nsel)
        m = 0
        for i in range(left.size):
            if sg[0, i] == 0:
                nl[m] = left[i]; nw[m] = width[i] / 2; m += 1
                nl[m] = left[i] + width[i] / 2; nw[m] = width[i] / 2; m += 1
            else:
                nl[m] = left[i]; nw[m] = width[i]; m += 1
        left = nl; width = nw
    return False, total
@njit(cache=True)
def certify_box_deep(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi, t0, t1, J, M0, rounds, arc_cap):
    """certify_box without the stall break and with a configurable arc cap (same refinement sequence)."""
    cmid, crad, dcen, dwid, cmax, rr = box_coeffs(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi)
    left = np.arange(M0) * (2 * math.pi / M0)
    width = np.full(M0, 2 * math.pi / M0)
    total = 999
    for rd in range(rounds + 1):
        sg, hopeless = arc_signs(cmid, crad, dcen, dwid, cmax, rr, t0, t1, left + width / 2, width / 2 + ARC_PAD, J)
        total = dp_count(sg)
        if total <= LIMIT:
            return True, total
        if rd == rounds or hopeless or left.size > arc_cap:
            break
        nsel = 0
        for i in range(left.size):
            if sg[0, i] == 0:
                nsel += 1
        if nsel == 0:
            break
        nl = np.empty(left.size + nsel); nw = np.empty(left.size + nsel)
        m = 0
        for i in range(left.size):
            if sg[0, i] == 0:
                nl[m] = left[i]; nw[m] = width[i] / 2; m += 1
                nl[m] = left[i] + width[i] / 2; nw[m] = width[i] / 2; m += 1
            else:
                nl[m] = left[i]; nw[m] = width[i]; m += 1
        left = nl; width = nw
    return False, total
